class MyStack<T>{private final Object[] items;private int top=-1;MyStack(int size){items=new Object[size];}void push(T value){if(top==items.length-1){System.out.println("Stack is full!");return;}items[++top]=value;}@SuppressWarnings("unchecked") T pop(){if(top<0){System.out.println("Stack is empty!");return null;}T value=(T)items[top];items[top--]=null;return value;}@SuppressWarnings("unchecked") T peek(){if(top<0){System.out.println("Stack is empty!");return null;}return (T)items[top];}boolean isEmpty(){return top<0;}}
public class Main {public static void main(String[] args){MyStack<Integer> a=new MyStack<>(5);a.push(10);a.push(20);a.push(30);System.out.println("Integer pop: "+a.pop());System.out.println("Integer peek: "+a.peek());MyStack<String>s=new MyStack<>(5);s.push("Java");s.push("Python");s.push("C++");System.out.println("String pop: "+s.pop());System.out.println("String peek: "+s.peek());while(!s.isEmpty())s.pop();System.out.println("Empty pop:");s.pop();}}
